// AUTO-GENERATED by socialcue-shared/scripts/sync.js — do not edit. Edit ../../../socialcue-shared/src and re-run `npm run sync`.
/**
 * Shared data shapes for Social Cue (zod).
 *
 * Distilled from the old website `shared/schema.ts` (brands, opportunities) but
 * stripped for the local model: no users/Stripe/sessionProfiles. These describe the
 * config file and the local SQLite rows shared by the plugin and the extension.
 */
import { z } from 'zod';

/** A brand the user wants to find conversations worth joining for. */
export const BrandSchema = z.object({
  id: z.string(),
  name: z.string().min(1),
  url: z.string().url().or(z.literal('')).default(''),
  tagline: z.string().default(''),
  shortDescription: z.string().default(''),
  tags: z.array(z.string()).default([]),
  aboutBrand: z.string().default(''),
  // Optional absolute path to the brand's existing project folder (repo root,
  // design docs, images — whatever the user already has). No structure is
  // imposed: agents explore it at submission time to find reusable assets.
  // Empty = unset. Set automatically by setup when running from that folder.
  projectPath: z.string().default(''),
  isActive: z.boolean().default(true),
});

/**
 * A configured social account / login the plugin can drive.
 * In the local model there is no uploaded session — this just names which
 * dedicated Chrome profile and platform we target. Cookies live in the profile.
 */
export const AccountSchema = z.object({
  platform: z.string(), // e.g. "reddit", "twitter"
  label: z.string().default(''),
  enabled: z.boolean().default(true),
  notes: z.string().default(''),
});

export const StrategyWeightsSchema = z.object({
  search: z.number().min(0).max(100).default(34),
  feed: z.number().min(0).max(100).default(33),
  trending: z.number().min(0).max(100).default(33),
});

/** Connection to the dedicated Chrome profile driven over CDP. */
export const BrowserConfigSchema = z.object({
  // Host:port the user launched Chrome with (--remote-debugging-port).
  cdpUrl: z.string().default('http://127.0.0.1:9222'),
  // Optional: a user-data-dir path, for docs/helpers that launch Chrome.
  profilePath: z.string().optional(),
});

/**
 * The localhost bridge (Pro): a loopback-only HTTP server hosted by the plugin
 * that unifies both sensors' opportunities and serves the dashboard. The token
 * pairs the extension/dashboard with the server; it never leaves the machine.
 */
export const BridgeConfigSchema = z.object({
  port: z.number().int().min(1024).max(65535).default(8377),
  // Pairing token (base64url). Generated on first `bridge start`; empty = not yet generated.
  token: z.string().default(''),
});

/**
 * Postiz connection (Content Strategy pillar) — the second, strictly opt-in
 * outbound integration. Dormant until the user pastes an API key; the key and
 * the content the user composes go only to their own Postiz endpoint (cloud
 * or self-hosted), never to Social Cue.
 */
export const PostizConfigSchema = z.object({
  // Postiz cloud default; self-hosted users point this at <host>/api/public/v1.
  apiUrl: z.string().default('https://api.postiz.com/public/v1'),
  // Empty = feature off (opt-in).
  apiKey: z.string().default(''),
  // Brand id -> Postiz integration ids for that brand's accounts (e.g. three
  // X accounts, one per brand). Drives channel defaults when composing and
  // when agents submit content without explicit channels.
  channelMap: z.record(z.array(z.string())).default({}),
});

/**
 * Directory submission (Pro): the email the user signed into inside the
 * dedicated Social Cue Chrome. Directory accounts get created on this address
 * (OAuth "Continue with Google" or email/password), and the driving agent reads
 * verification mail by opening the user's own webmail in a second tab. Social
 * Cue never stores the mailbox password — only the address.
 */
export const DirectoriesConfigSchema = z.object({
  // Empty = not configured yet (setup / the submit command ask for it).
  signupEmail: z.string().default(''),
  // Optional webmail URL override; empty = derived from the address's domain
  // (gmail.com -> mail.google.com, proton.me -> mail.proton.me, ...). Set it for
  // custom domains (e.g. Google Workspace -> https://mail.google.com).
  webmailUrl: z.string().default(''),
});

/** The whole `.socialdiscovery/config.json` document. */
export const ConfigSchema = z.object({
  version: z.literal(1).default(1),
  brands: z.array(BrandSchema).default([]),
  accounts: z.array(AccountSchema).default([]),
  platforms: z.array(z.string()).default(['reddit']), // Reddit-first
  browser: BrowserConfigSchema.default({}),
  strategyWeights: StrategyWeightsSchema.default({}),
  autoLike: z.boolean().default(false),
  // Assisted posting never clicks submit: pre-fill only, and a "Post & Submit"
  // click still marks the reply posted (the user submits in the browser).
  dryRunPosts: z.boolean().default(false),
  engagementRatio: z.number().min(0).max(1).default(0.8),
  collectMemeIdeas: z.boolean().default(false),
  maxTurnsPerPlatform: z.number().int().positive().default(75),
  seenUrlsTtlDays: z.number().int().positive().default(90),
  bridge: BridgeConfigSchema.default({}),
  // Pro license key (SC1-…), verified fully offline by the plugin's lib/license.js.
  // Empty = free tier. Gates the action layer (assisted posting), never discovery.
  // Now short-lived + auto-refreshed from licenseServerUrl using licenseAccountToken.
  license: z.string().default(''),
  // Opaque account token (scacct_…) from the Pro subscription. The plugin presents
  // it to licenseServerUrl to pull a fresh signed key while the subscription is
  // active — the ONLY thing sent off-machine, and only the token (never page data).
  licenseAccountToken: z.string().default(''),
  // Where to fetch fresh license keys (the Social Cue licensing site).
  licenseServerUrl: z.string().default('https://trysocialcue.com'),
  // Content Strategy: the user's own Postiz account for scheduling original
  // posts. Opt-in — see PostizConfigSchema.
  postiz: PostizConfigSchema.default({}),
  // Directory submission (Pro): the signup email the user is logged into in the
  // dedicated Chrome (+ optional webmail URL). See DirectoriesConfigSchema.
  directories: DirectoriesConfigSchema.default({}),
});

export const OpportunityStatus = {
  NEW: 'new',
  REVIEWED: 'reviewed',
  APPROVED: 'approved',
  POSTED: 'posted',
  SKIPPED: 'skipped',
  FAILED: 'failed',
};

/** A discovered opportunity (written by either sensor to the local store). */
export const OpportunitySchema = z.object({
  id: z.string(),
  brandId: z.string().nullable().default(null),
  // Raw brand name as reported by the sensor (the extension has no brand ids);
  // kept alongside brandId so a failed name→id resolution still displays.
  brandName: z.string().default(''),
  runId: z.string().nullable().default(null),
  source: z.enum(['plugin', 'extension']).default('plugin'),
  platform: z.string(),
  platformUrl: z.string(),
  title: z.string().default(''),
  context: z.string().default(''),
  opportunityType: z.string().default('general_comment'),
  relevanceScore: z.number().min(0).max(10).nullable().default(null),
  relevanceReason: z.string().default(''),
  suggestedReply: z.string().default(''),
  suggestedAction: z.string().default(''),
  status: z.enum(['new', 'reviewed', 'approved', 'posted', 'skipped', 'failed']).default('new'),
  screenshotPath: z.string().nullable().default(null),
  createdAt: z.string().default(() => new Date().toISOString()),
  // When the source post was published on the platform (ISO), as opposed to
  // createdAt = when we discovered it. Nullable: not every sensor can read it.
  // Drives the "fresh" badge (see freshness.js); never affects ordering.
  publishedAt: z.string().nullable().default(null),
});

/** @returns {object} a fully-defaulted config */
export function emptyConfig() {
  return ConfigSchema.parse({});
}
